-- Morph migration (morph 0.1.0). Generated by `morph init`; review it, then run `supabase db push`.
-- Everything here runs as the signed-in viewer: views are security_invoker and functions are SECURITY INVOKER.
-- To remove Morph: drop the morph_r_* views, the morph_* functions and the morph_audit table.

-- 1. Action allow-list. Table and column names for writes come only from here.
create or replace function public.morph__action_def() returns jsonb language sql immutable security invoker set search_path = '' as $fn$
  select $json${
  "undo_days": 30,
  "actor": {
    "schema": "public",
    "table": "users",
    "pk": "id",
    "display": "name"
  },
  "actions": {
    "activities.user_id": {
      "id": "activities.user_id",
      "kind": "set_fk",
      "enabled": false,
      "schema": "public",
      "table": "activities",
      "column": "user_id",
      "col_type": "uuid",
      "pk": "id",
      "pk_type": "uuid",
      "display": "kind",
      "side_effects": [],
      "bulk_max": 25,
      "target": {
        "schema": "public",
        "table": "users",
        "pk": "id",
        "display": "name"
      }
    },
    "deals.owner_id": {
      "id": "deals.owner_id",
      "kind": "set_fk",
      "enabled": true,
      "schema": "public",
      "table": "deals",
      "column": "owner_id",
      "col_type": "uuid",
      "pk": "id",
      "pk_type": "uuid",
      "display": "name",
      "side_effects": [
        "updated_at"
      ],
      "bulk_max": 25,
      "target": {
        "schema": "public",
        "table": "users",
        "pk": "id",
        "display": "name"
      }
    },
    "deals.stage": {
      "id": "deals.stage",
      "kind": "set_enum",
      "enabled": true,
      "schema": "public",
      "table": "deals",
      "column": "stage",
      "col_type": "\"public\".\"deal_stage\"",
      "pk": "id",
      "pk_type": "uuid",
      "display": "name",
      "side_effects": [
        "stage_changed_at"
      ],
      "bulk_max": 25,
      "values": [
        "lead",
        "qualified",
        "proposal",
        "won",
        "lost"
      ],
      "terminal": [
        "won",
        "lost"
      ],
      "labels": {
        "lead": "Lead",
        "qualified": "Qualified",
        "proposal": "Proposal",
        "won": "Won",
        "lost": "Lost"
      }
    },
    "users.role": {
      "id": "users.role",
      "kind": "set_enum",
      "enabled": false,
      "schema": "public",
      "table": "users",
      "column": "role",
      "col_type": "text",
      "pk": "id",
      "pk_type": "uuid",
      "display": "name",
      "side_effects": [],
      "bulk_max": 25,
      "values": [
        "rep",
        "sales_manager"
      ],
      "terminal": [],
      "labels": {
        "rep": "Rep",
        "sales_manager": "Sales manager"
      }
    }
  }
}$json$::jsonb
$fn$;
revoke all on function public.morph__action_def() from public, anon;
grant execute on function public.morph__action_def() to authenticated;

-- 2. Who can read the audit log (default: only the person who acted).
create or replace function public.morph__can_read_audit(p_actor uuid) returns boolean language sql stable security invoker set search_path = '' as $fn$ select p_actor = auth.uid() $fn$;
revoke all on function public.morph__can_read_audit(uuid) from public, anon;
grant execute on function public.morph__can_read_audit(uuid) to authenticated;

-- 3. Audit table (MO-708).
create table if not exists public.morph_audit (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  actor uuid not null default auth.uid(),
  actor_name text,
  action text not null,
  table_name text not null,
  row_count integer not null,
  rows jsonb not null,
  to_value text,
  to_display text,
  source text not null default 'component' check (source in ('component', 'mcp')),
  undone_at timestamptz,
  undone_by uuid,
  undo_partial boolean not null default false
);
create index if not exists morph_audit_actor_created_idx on public.morph_audit (actor, created_at desc);

alter table public.morph_audit enable row level security;

-- Rows are written only from inside morph_apply_action / morph_undo, which
-- set a transaction-local flag that clients can't set through PostgREST.
drop policy if exists morph_audit_select on public.morph_audit;
create policy morph_audit_select on public.morph_audit for select to authenticated
  using (public.morph__can_read_audit(actor));
drop policy if exists morph_audit_insert on public.morph_audit;
create policy morph_audit_insert on public.morph_audit for insert to authenticated
  with check (actor = auth.uid() and current_setting('morph.writer', true) = 'apply');
drop policy if exists morph_audit_update on public.morph_audit;
create policy morph_audit_update on public.morph_audit for update to authenticated
  using (actor = auth.uid())
  with check (actor = auth.uid() and current_setting('morph.writer', true) = 'undo');

revoke all on public.morph_audit from public, anon, authenticated;
grant select, insert on public.morph_audit to authenticated;
grant update (undone_at, undone_by, undo_partial) on public.morph_audit to authenticated;

-- 4. Preview, apply, undo (MO-705 – MO-707).
-- Looks up an action in the allow-list. Raises MO001 when unknown or disabled.
create or replace function public.morph__def(p_action text, p_require_enabled boolean default true)
returns jsonb language plpgsql stable security invoker set search_path = '' as $fn$
declare d jsonb;
begin
  d := public.morph__action_def() -> 'actions' -> p_action;
  if d is null then
    raise exception using errcode = 'MO001', message = format('%s is not a Morph action in this project.', coalesce(p_action, 'That'));
  end if;
  if p_require_enabled and not coalesce((d ->> 'enabled')::boolean, false) then
    raise exception using errcode = 'MO001', message = format('%s is turned off in morph/actions.json.', p_action);
  end if;
  return d;
end $fn$;

-- Display name of the signed-in viewer, from the scanned profile table.
create or replace function public.morph__actor_name()
returns text language plpgsql stable security invoker set search_path = '' as $fn$
declare a jsonb := public.morph__action_def() -> 'actor'; v text;
begin
  if a is null or auth.uid() is null then return null; end if;
  execute format('select %I::text from %I.%I where %I::text = $1', a ->> 'display', a ->> 'schema', a ->> 'table', a ->> 'pk')
    into v using auth.uid()::text;
  return v;
exception when others then return null;
end $fn$;

-- UPDATE policies that apply to a table, read live from the catalog.
create or replace function public.morph__policies(p_schema text, p_table text)
returns jsonb language sql stable security invoker set search_path = '' as $fn$
  select coalesce(jsonb_agg(p.policyname order by p.policyname), '[]'::jsonb)
  from pg_catalog.pg_policies p
  where p.schemaname = p_schema and p.tablename = p_table and p.cmd in ('UPDATE', 'ALL')
$fn$;

-- Permission probe (MO-704): cheap check before showing action buttons.
create or replace function public.morph_action_info(action_id text)
returns jsonb language plpgsql stable security invoker set search_path = '' as $fn$
declare d jsonb; can boolean;
begin
  d := public.morph__def(action_id, false);
  can := coalesce((d ->> 'enabled')::boolean, false)
    and auth.uid() is not null
    and pg_catalog.has_column_privilege(format('%I.%I', d ->> 'schema', d ->> 'table'), d ->> 'column', 'UPDATE')
    and jsonb_array_length(public.morph__policies(d ->> 'schema', d ->> 'table')) > 0;
  return jsonb_build_object('action', action_id, 'canAct', can, 'policies', public.morph__policies(d ->> 'schema', d ->> 'table'));
end $fn$;

-- Shared validation for preview and apply. Returns the target display name.
create or replace function public.morph__check(d jsonb, p_ids text[], p_to text)
returns text language plpgsql stable security invoker set search_path = '' as $fn$
declare n int := coalesce(array_length(p_ids, 1), 0); v_display text; rc int;
begin
  if auth.uid() is null then
    raise exception using errcode = 'MO010', message = 'Sign in to take actions.';
  end if;
  if n = 0 then
    raise exception using errcode = 'MO002', message = 'Pick at least one row.';
  end if;
  if n > (d ->> 'bulk_max')::int then
    raise exception using errcode = 'MO002', message = format('You can change up to %s rows in one action. You picked %s.', d ->> 'bulk_max', n),
      hint = 'Select fewer rows, or raise bulkMax in morph/actions.json (hard limit 200).';
  end if;
  if p_to is null or p_to = '' then
    raise exception using errcode = 'MO003', message = 'Choose a new value first.';
  end if;
  if d ->> 'kind' = 'set_enum' then
    if not (d -> 'values') ? p_to then
      raise exception using errcode = 'MO003', message = format('"%s" is not an allowed value for %s.', p_to, d ->> 'column'),
        detail = (d -> 'values')::text;
    end if;
    return coalesce(d -> 'labels' ->> p_to, p_to);
  end if;
  -- set_fk: the target must be visible to the viewer (RLS on the target table).
  begin
    execute format('select %s from %I.%I where %I::text = $1',
      case when d -> 'target' ->> 'display' is null then 'null::text' else format('%I::text', d -> 'target' ->> 'display') end,
      d -> 'target' ->> 'schema', d -> 'target' ->> 'table', d -> 'target' ->> 'pk')
      into v_display using p_to;
    get diagnostics rc = row_count;
  exception when invalid_text_representation then rc := 0;
  end;
  if rc = 0 then
    raise exception using errcode = 'MO004', message = 'That person isn''t visible to you, so you can''t assign to them.';
  end if;
  return coalesce(v_display, p_to);
end $fn$;

-- MO-705: dry run as the viewer, rolled back. Shows every row and field that would change.
create or replace function public.morph_preview_action(action jsonb)
returns jsonb language plpgsql volatile security invoker set search_path = '' as $fn$
declare
  d jsonb := public.morph__def(action ->> 'action');
  v_to text := action ->> 'to';
  v_ids text[];
  v_change text[] := '{}';
  v_to_display text;
  v_rows jsonb := '[]'::jsonb;
  v_allowed int := 0;
  v_side_sel text;
  v_side_set text;
  r record;
begin
  select coalesce(array_agg(distinct x), '{}') into v_ids from jsonb_array_elements_text(coalesce(action -> 'ids', '[]'::jsonb)) x;
  v_to_display := public.morph__check(d, v_ids, v_to);

  select coalesce(string_agg(format('%L, %I', s, s), ', '), '') , coalesce(string_agg(format(', %I = now()', s), ''), '')
    into v_side_sel, v_side_set
    from jsonb_array_elements_text(coalesce(d -> 'side_effects', '[]'::jsonb)) s;

  for r in execute format(
    'select %I::text as id, %s as display, to_jsonb(%I) as cur, xmin::text as version, jsonb_build_object(%s) as side from %I.%I where %I = any($1::%s[]) order by 2',
    d ->> 'pk',
    case when d ->> 'display' is null then 'null::text' else format('%I::text', d ->> 'display') end,
    d ->> 'column', v_side_sel, d ->> 'schema', d ->> 'table', d ->> 'pk', d ->> 'pk_type')
    using v_ids
  loop
    v_rows := v_rows || jsonb_build_object(
      'id', r.id, 'display', r.display, 'field', d ->> 'column',
      'before', r.cur, 'after', to_jsonb(v_to), 'version', r.version,
      'skipped', case when r.cur #>> '{}' = v_to then 'already' else null end,
      'sideEffects', (select coalesce(jsonb_object_agg(k, jsonb_build_object('before', v, 'after', 'now')), '{}'::jsonb) from jsonb_each(r.side) e(k, v)));
    if r.cur #>> '{}' is distinct from v_to then v_change := v_change || r.id; end if;
  end loop;

  if jsonb_array_length(v_rows) < array_length(v_ids, 1) then
    raise exception using errcode = 'MO005',
      message = format('%s of the rows you picked aren''t visible to you.', array_length(v_ids, 1) - jsonb_array_length(v_rows)),
      hint = 'Reload the report. Someone may have reassigned them, or your access changed.';
  end if;

  -- Dry run: run the real UPDATE under the viewer's policies, count rows, roll back.
  if array_length(v_change, 1) > 0 then
    begin
      execute format('update %I.%I set %I = $1::%s%s where %I = any($2::%s[])',
        d ->> 'schema', d ->> 'table', d ->> 'column', d ->> 'col_type', v_side_set, d ->> 'pk', d ->> 'pk_type')
        using v_to, v_change;
      get diagnostics v_allowed = row_count;
      raise exception using errcode = 'MOROL';
    exception
      when sqlstate 'MOROL' then null;
      when insufficient_privilege then v_allowed := 0;
    end;
  end if;

  return jsonb_build_object(
    'action', d ->> 'id', 'kind', d ->> 'kind', 'to', v_to, 'toDisplay', v_to_display,
    'rows', v_rows, 'changed', coalesce(array_length(v_change, 1), 0), 'allowed', v_allowed,
    'bulkMax', (d ->> 'bulk_max')::int,
    'policies', public.morph__policies(d ->> 'schema', d ->> 'table'),
    'undoDays', (public.morph__action_def() ->> 'undo_days')::int,
    'undoUntil', now() + make_interval(days => (public.morph__action_def() ->> 'undo_days')::int),
    'terminal', coalesce((d -> 'terminal') ? v_to, false),
    'actor', public.morph__actor_name());
end $fn$;

-- MO-706: all-or-nothing apply with a version check per row and one audit row.
create or replace function public.morph_apply_action(action jsonb, source text default 'component')
returns jsonb language plpgsql volatile security invoker set search_path = '' as $fn$
declare
  d jsonb := public.morph__def(action ->> 'action');
  v_to text := action ->> 'to';
  v_expected jsonb := action -> 'expected';
  v_ids text[];
  v_change text[] := '{}';
  v_to_display text;
  v_before jsonb := '{}'::jsonb;
  v_conflicts jsonb := '[]'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_side_sel text;
  v_side_set text;
  v_count int := 0;
  v_audit uuid;
  r record;
begin
  if source not in ('component', 'mcp') then source := 'component'; end if;
  select coalesce(array_agg(distinct x), '{}') into v_ids from jsonb_array_elements_text(coalesce(action -> 'ids', '[]'::jsonb)) x;
  v_to_display := public.morph__check(d, v_ids, v_to);
  if v_expected is null or jsonb_typeof(v_expected) <> 'object' then
    raise exception using errcode = 'MO009', message = 'Preview the change before applying it.';
  end if;

  select coalesce(string_agg(format('%L, %I', s, s), ', '), ''), coalesce(string_agg(format(', %I = now()', s), ''), '')
    into v_side_sel, v_side_set
    from jsonb_array_elements_text(coalesce(d -> 'side_effects', '[]'::jsonb)) s;

  -- Lock the rows as the viewer. Rows the viewer can't update are not returned.
  for r in execute format(
    'select %I::text as id, %s as display, to_jsonb(%I) as cur, xmin::text as version, jsonb_build_object(%s) as side from %I.%I where %I = any($1::%s[]) for update',
    d ->> 'pk',
    case when d ->> 'display' is null then 'null::text' else format('%I::text', d ->> 'display') end,
    d ->> 'column', v_side_sel, d ->> 'schema', d ->> 'table', d ->> 'pk', d ->> 'pk_type')
    using v_ids
  loop
    if v_expected -> r.id is null or v_expected -> r.id ->> 'version' is distinct from r.version then
      v_conflicts := v_conflicts || jsonb_build_object('id', r.id, 'display', r.display, 'now', r.cur, 'expected', v_expected -> r.id -> 'value');
    elsif r.cur #>> '{}' is distinct from v_to then
      v_change := v_change || r.id;
      v_before := v_before || jsonb_build_object(r.id, jsonb_build_object('display', r.display, 'before', jsonb_build_object(d ->> 'column', r.cur) || r.side));
    end if;
    v_count := v_count + 1;
  end loop;

  if v_count < array_length(v_ids, 1) then
    raise exception using errcode = 'MO005',
      message = format('Your access doesn''t allow changing %s of these rows.', array_length(v_ids, 1) - v_count),
      hint = 'Your app''s row-level security decides what you can change. Nothing was written.';
  end if;
  if jsonb_array_length(v_conflicts) > 0 then
    raise exception using errcode = 'MO006',
      message = format('%s of these rows changed since you previewed. Nothing was written.', jsonb_array_length(v_conflicts)),
      detail = v_conflicts::text, hint = 'Reload and preview again.';
  end if;
  if coalesce(array_length(v_change, 1), 0) = 0 then
    raise exception using errcode = 'MO002', message = 'Nothing to change: every row already has that value.';
  end if;

  begin
    for r in execute format('update %I.%I set %I = $1::%s%s where %I = any($2::%s[]) returning %I::text as id, to_jsonb(%I) as val, jsonb_build_object(%s) as side',
      d ->> 'schema', d ->> 'table', d ->> 'column', d ->> 'col_type', v_side_set, d ->> 'pk', d ->> 'pk_type', d ->> 'pk', d ->> 'column', v_side_sel)
      using v_to, v_change
    loop
      v_rows := v_rows || jsonb_build_object('id', r.id, 'display', v_before -> r.id ->> 'display',
        'before', v_before -> r.id -> 'before', 'after', jsonb_build_object(d ->> 'column', r.val) || r.side);
    end loop;
  exception when insufficient_privilege then
    raise exception using errcode = 'MO005', message = 'Your access doesn''t allow this change. Nothing was written.',
      hint = 'Your app''s row-level security decides what you can change.';
  end;
  if jsonb_array_length(v_rows) <> array_length(v_change, 1) then
    raise exception using errcode = 'MO005',
      message = format('Your access doesn''t allow changing %s of these rows. Nothing was written.', array_length(v_change, 1) - jsonb_array_length(v_rows));
  end if;

  perform pg_catalog.set_config('morph.writer', 'apply', true);
  insert into public.morph_audit (actor, actor_name, action, table_name, row_count, rows, to_value, to_display, source)
  values (auth.uid(), public.morph__actor_name(), d ->> 'id', d ->> 'table', jsonb_array_length(v_rows), v_rows, v_to, v_to_display, source)
  returning id into v_audit;
  perform pg_catalog.set_config('morph.writer', '', true);

  return jsonb_build_object('auditId', v_audit, 'changed', jsonb_array_length(v_rows), 'rows', v_rows,
    'undoUntil', now() + make_interval(days => (public.morph__action_def() ->> 'undo_days')::int));
end $fn$;

-- MO-707: restores before values if each row still has the after value.
create or replace function public.morph_undo(audit_id uuid, partial boolean default false)
returns jsonb language plpgsql volatile security invoker set search_path = '' as $fn$
declare
  a public.morph_audit;
  d jsonb;
  v_days int := (public.morph__action_def() ->> 'undo_days')::int;
  v_conflicts jsonb := '[]'::jsonb;
  v_ok jsonb := '[]'::jsonb;
  v_cur jsonb;
  v_cols text;
  v_rc int;
  v_restored int := 0;
  r jsonb;
  c record;
begin
  if auth.uid() is null then
    raise exception using errcode = 'MO010', message = 'Sign in to undo actions.';
  end if;
  select * into a from public.morph_audit where id = audit_id;
  if not found then
    raise exception using errcode = 'MO011', message = 'That action isn''t in your log.';
  end if;
  if a.undone_at is not null then
    raise exception using errcode = 'MO008', message = 'This action was already undone.';
  end if;
  if a.created_at < now() - make_interval(days => v_days) then
    raise exception using errcode = 'MO007', message = 'Undo window closed.',
      hint = format('Actions can be undone for %s days.', v_days);
  end if;
  d := public.morph__def(a.action, false);

  for r in select * from jsonb_array_elements(a.rows) loop
    v_cur := null;
    execute format('select to_jsonb(%I) from %I.%I where %I = $1::%s for update',
      d ->> 'column', d ->> 'schema', d ->> 'table', d ->> 'pk', d ->> 'pk_type')
      into v_cur using r ->> 'id';
    get diagnostics v_rc = row_count;
    if v_rc = 0 or v_cur is distinct from (r -> 'after' -> (d ->> 'column')) then
      select x.actor_name, x.created_at into c from public.morph_audit x
        where x.id <> a.id and x.created_at > a.created_at and x.action = a.action and x.rows @> jsonb_build_array(jsonb_build_object('id', r ->> 'id'))
        order by x.created_at desc limit 1;
      v_conflicts := v_conflicts || jsonb_build_object('id', r ->> 'id', 'display', r ->> 'display',
        'now', v_cur, 'expected', r -> 'after' -> (d ->> 'column'),
        'changedBy', c.actor_name, 'changedAt', c.created_at);
    else
      v_ok := v_ok || r;
    end if;
  end loop;

  if jsonb_array_length(v_conflicts) > 0 and not partial then
    raise exception using errcode = 'MO006',
      message = format('%s of these rows changed since, so undo stopped. Nothing was restored.', jsonb_array_length(v_conflicts)),
      detail = v_conflicts::text, hint = 'Undo the rest with partial undo.';
  end if;

  for r in select * from jsonb_array_elements(v_ok) loop
    select string_agg(format('%I', k), ', ') into v_cols from jsonb_object_keys(r -> 'before') k;
    begin
      execute format('update %I.%I set (%s) = (select %s from jsonb_populate_record(null::%I.%I, $1)) where %I = $2::%s',
        d ->> 'schema', d ->> 'table', v_cols, v_cols, d ->> 'schema', d ->> 'table', d ->> 'pk', d ->> 'pk_type')
        using r -> 'before', r ->> 'id';
      get diagnostics v_rc = row_count;
    exception when insufficient_privilege then v_rc := 0;
    end;
    if v_rc <> 1 then
      raise exception using errcode = 'MO005', message = format('Your access doesn''t allow restoring %s. Nothing was restored.', coalesce(r ->> 'display', r ->> 'id'));
    end if;
    v_restored := v_restored + 1;
  end loop;

  perform pg_catalog.set_config('morph.writer', 'undo', true);
  update public.morph_audit set undone_at = now(), undone_by = auth.uid(), undo_partial = jsonb_array_length(v_conflicts) > 0
    where id = a.id;
  perform pg_catalog.set_config('morph.writer', '', true);

  return jsonb_build_object('auditId', a.id, 'restored', v_restored, 'partial', jsonb_array_length(v_conflicts) > 0, 'conflicts', v_conflicts);
end $fn$;

revoke all on function public.morph__def(text, boolean) from public, anon;
revoke all on function public.morph__actor_name() from public, anon;
revoke all on function public.morph__policies(text, text) from public, anon;
revoke all on function public.morph__check(jsonb, text[], text) from public, anon;
revoke all on function public.morph_action_info(text) from public, anon;
revoke all on function public.morph_preview_action(jsonb) from public, anon;
revoke all on function public.morph_apply_action(jsonb, text) from public, anon;
revoke all on function public.morph_undo(uuid, boolean) from public, anon;
grant execute on function public.morph__def(text, boolean) to authenticated;
grant execute on function public.morph__actor_name() to authenticated;
grant execute on function public.morph__policies(text, text) to authenticated;
grant execute on function public.morph__check(jsonb, text[], text) to authenticated;
grant execute on function public.morph_action_info(text) to authenticated;
grant execute on function public.morph_preview_action(jsonb) to authenticated;
grant execute on function public.morph_apply_action(jsonb, text) to authenticated;
grant execute on function public.morph_undo(uuid, boolean) to authenticated;

-- 5. Report views (MO-402). One security_invoker view per kept report.
-- Report: Deals by stage
create or replace view "public"."morph_r_deals_by_stage" with (security_invoker = true) as
select
  "deals"."id"::text as "_morph_id",
  "deals"."xmin"::text as "_morph_version",
  "deals"."name" as "name",
  "deals"."stage" as "stage",
  "users"."name" as "owner",
  "deals"."value_zar" as "value_zar",
  (current_date - "deals"."stage_changed_at"::date) as "days_in_stage",
  "deals"."owner_id" as "owner_id"
from "public"."deals" as "deals"
left join "public"."users" as "users" on "users"."id" = "deals"."owner_id"
where "deals"."stage" not in ('won', 'lost');
revoke all on "public"."morph_r_deals_by_stage" from public, anon;
grant select on "public"."morph_r_deals_by_stage" to authenticated;

-- Report: Stuck deals
create or replace view "public"."morph_r_stuck_deals" with (security_invoker = true) as
select
  "deals"."id"::text as "_morph_id",
  "deals"."xmin"::text as "_morph_version",
  "deals"."name" as "name",
  "deals"."stage" as "stage",
  "users"."name" as "owner",
  "deals"."value_zar" as "value_zar",
  (current_date - "deals"."stage_changed_at"::date) as "days_in_stage",
  "deals"."owner_id" as "owner_id"
from "public"."deals" as "deals"
left join "public"."users" as "users" on "users"."id" = "deals"."owner_id"
where "deals"."stage" not in ('won', 'lost')
  and (current_date - "deals"."stage_changed_at"::date) > 14;
revoke all on "public"."morph_r_stuck_deals" from public, anon;
grant select on "public"."morph_r_stuck_deals" to authenticated;

